"""Direct runtime for AOT-compiled CuTe kernels.

The AOT `.so` (built by `scripts/precompile/cute_aot_build.py`) exports
three symbols per variant:

    _mlir_<prefix>_cuda_init(void **packed)          # packed = [&lib_ptr, &err]
    _mlir_<prefix>_cuda_load_to_device(void **)      # packed = [&lib_ptr, &dev, &err]
    _mlir_<prefix>__mlir_ciface_<fn>(void **, int32) # packed as per header:
        [&tensor_struct_0, ..., &scalar_0, ..., &stream, &err_slot]

Windows PE sections are produced from raw LLVM IR internally, but the build
links a C adapter that exposes this same packed `_mlir_*` ABI. The Python
runtime never calls raw LLVM aggregate entry points directly.

Each `Tensor_mX_t` struct is `{void *data; int32_t dynamic_shapes[N];
int64_t dynamic_strides[M];}` — one `MemrefStructSpec` per memref
describes which (N, M) apply and which dims the mask counts as dynamic.

`AotFamily` wraps the per-family lookup + cache + (optional) JIT
fallback so each dispatch module is a thin adapter: pack args in the
wrapper's declared order, call `ciface`. No per-family resolver code.

No `libcute_dsl_runtime.so` / `apache-tvm-ffi` dep at runtime. Pure
ctypes.
"""

import ctypes
import hashlib
import json
import os
import platform
import sys
import threading
from copy import deepcopy
from dataclasses import dataclass
from pathlib import Path
from types import MappingProxyType
from typing import Callable, Mapping

import torch


_SHARED_LIB_EXT = ".dll" if sys.platform == "win32" else ".so"

# Lazily-resolved libc.memfd_create, used to dlopen a decrypted AOT `.so`
# straight from an anonymous in-RAM file descriptor — no plaintext `.so`
# ever touches the filesystem. None on platforms without memfd (Windows /
# pre-3.17 kernels); those fall back to a decrypt-to-tempfile + unlink path.
_MEMFD_CREATE = None
if sys.platform != "win32":
    try:
        _libc = ctypes.CDLL("libc.so.6", use_errno=True)
        _libc.memfd_create.restype = ctypes.c_int
        _libc.memfd_create.argtypes = [ctypes.c_char_p, ctypes.c_uint]
        _MEMFD_CREATE = _libc.memfd_create
    except (OSError, AttributeError):
        _MEMFD_CREATE = None

_MFD_CLOEXEC = 0x0001


def _dlopen_from_bytes(
    so_bytes: bytes,
    tag: str,
    *,
    identity: str | None = None,
) -> ctypes.CDLL:
    """Load a shared object from raw bytes with no plaintext disk artifact.

    Preferred path: `memfd_create` an anonymous in-RAM fd, write the bytes,
    and `dlopen("/proc/self/fd/<n>")`. The fd is never linked into the
    filesystem, so the decrypted `.so` only exists in this process's memory.
    One-time per variant (cached by the caller) — zero per-execution cost.

    The memfd fd is retained for process lifetime, keyed by the shared-object
    content hash. Linux may retain a loader mapping/cache after Python releases
    the `CDLL`; tying the fd only to that object therefore permits a later fd
    reuse to present a different binary at the same `/proc/self/fd/<n>` path.
    Process-lifetime ownership keeps every loaded binary's pathname identity
    unique and is bounded by the number of distinct AOT variants loaded.

    Fallback (no memfd, e.g. old kernels): write to a private temp file with
    0600 perms, dlopen it, then immediately `unlink` so the only reference is
    the open handle held by the loader — minimising the on-disk window. (The
    tempfile path is per-call unique, so it has no pathname-reuse hazard.)
    """
    if _MEMFD_CREATE is not None:
        identity = identity or hashlib.sha256(so_bytes).hexdigest()
        with _PROCESS_MEMFD_LOCK:
            handle = _PROCESS_MEMFDS.get(identity)
            if handle is not None:
                dll = ctypes.CDLL(handle.path, mode=ctypes.RTLD_LOCAL)
                dll._kk_memfd = handle
                return dll

            fd = _MEMFD_CREATE(b"kk_aot", _MFD_CLOEXEC)
            if fd >= 0:
                try:
                    # Write via a dup so the original fd stays open after the
                    # context manager closes the dup.
                    with os.fdopen(os.dup(fd), "wb", closefd=True) as fh:
                        fh.write(so_bytes)
                    dll = ctypes.CDLL(f"/proc/self/fd/{fd}", mode=ctypes.RTLD_LOCAL)
                except Exception:
                    os.close(fd)
                    raise
                handle = _MemfdHandle(fd)
                _PROCESS_MEMFDS[identity] = handle
                dll._kk_memfd = handle
                return dll

    import tempfile

    suffix = ".dll" if sys.platform == "win32" else ".so"
    fd, tmp_path = tempfile.mkstemp(suffix=suffix, prefix=f"kk_aot_{tag}_")
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(so_bytes)
        dll = ctypes.CDLL(tmp_path, mode=ctypes.RTLD_LOCAL)
    finally:
        # Unlink immediately: on Linux the open mapping keeps the inode alive
        # for the process while removing the name from the filesystem. On
        # Windows the file stays until handles close (best-effort cleanup).
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
    return dll


class _MemfdHandle:
    """Process-lifetime owner for one loaded memfd pathname identity."""

    __slots__ = ("_fd",)

    def __init__(self, fd: int) -> None:
        self._fd = fd

    @property
    def path(self) -> str:
        return f"/proc/self/fd/{self._fd}"


_PROCESS_MEMFDS: dict[str, _MemfdHandle] = {}
_PROCESS_MEMFD_LOCK = threading.Lock()

# ELF `e_machine` for the running CPU. The packed Linux stub must match the
# host CPU, not merely be ELF: the x86_64 cubin-bundles artifact is also staged
# on aarch64 Linux (Jetson/GH200), where an x86_64 `.so` cannot dlopen — so we
# reject it and fall back rather than fail in `_dlopen_from_bytes`.
_EM_X86_64 = 0x3E
_EM_AARCH64 = 0xB7
_HOST_E_MACHINE = {
    "x86_64": _EM_X86_64,
    "AMD64": _EM_X86_64,
    "aarch64": _EM_AARCH64,
    "arm64": _EM_AARCH64,
}.get(platform.machine())


def _so_bytes_match_host(so_bytes: bytes) -> bool:
    """True iff the binary container in `so_bytes` matches the running host's
    loadable format AND CPU, so `dlopen`/`LoadLibrary` can actually map it.

    Guards against loading a packed host wrapper whose ABI doesn't match the
    running platform — a Linux ELF on a Windows/Mac wheel, OR an x86_64 ELF on
    an aarch64 Linux host (the shared `cubin-bundles` artifact is built on
    x86_64 but also staged on Jetson/GH200). On a mismatch the caller falls
    back to a host-native loose `.so` / the JIT path instead of crashing.
    """
    head = so_bytes[:4]
    if sys.platform == "win32":
        return head[:2] == b"MZ"  # PE/COFF
    if sys.platform == "darwin":
        # Mach-O (thin: feedface/cefaedfe/feedfacf/cffaedfe) or fat (cafebabe).
        return head in (
            b"\xfe\xed\xfa\xce",
            b"\xce\xfa\xed\xfe",
            b"\xfe\xed\xfa\xcf",
            b"\xcf\xfa\xed\xfe",
            b"\xca\xfe\xba\xbe",
        )
    # Linux / other ELF platforms: require ELF magic, 64-bit class, AND a CPU
    # (`e_machine`) matching this host.
    if head != b"\x7fELF" or len(so_bytes) < 20:
        return False
    if so_bytes[4] != 2:  # EI_CLASS: must be ELFCLASS64
        return False
    le = "<" if so_bytes[5] == 1 else ">"
    import struct as _struct

    e_machine = _struct.unpack_from(le + "H", so_bytes, 0x12)[0]
    if _HOST_E_MACHINE is None:
        # Unknown host CPU mapping — fall back conservatively rather than
        # load a stub we can't verify.
        return False
    return e_machine == _HOST_E_MACHINE


