        ("lahf_lm",),
        ("popcnt",),
        ("pni", "sse3"),
        ("ssse3",),
        ("sse4_1",),
        ("sse4_2",),
        ("avx",),
        ("avx2",),
        ("bmi1",),
        ("bmi2",),
