_EXECUTABLE_BUFFERS = []
_CPUID_FN = None
_XGETBV_FN = None


def _linux_cpuinfo_flags() -> "set[str] | None":
    if not sys.platform.startswith("linux"):
        return None
    try:
        text = Path("/proc/cpuinfo").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    for line in text.splitlines():
        key, sep, value = line.partition(":")
        if sep and key.strip().lower() in ("flags", "features"):
            return set(value.strip().split())
    return None


def _x86_64_flags_support_level(flags: set[str], level: str) -> bool:
    return all(
        any(flag in flags for flag in aliases) for aliases in _X86_64_LEVEL_FLAGS[level]
    )


def _make_executable_function(code: bytes, restype, argtypes):
    if sys.platform == "win32":
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        virtual_alloc = kernel32.VirtualAlloc
        virtual_alloc.restype = ctypes.c_void_p
        virtual_alloc.argtypes = [
            ctypes.c_void_p,
            ctypes.c_size_t,
            ctypes.c_ulong,
            ctypes.c_ulong,
        ]
        addr = virtual_alloc(None, len(code), 0x3000, 0x40)
        if not addr:
            raise OSError(ctypes.get_last_error(), "VirtualAlloc failed")
        ctypes.memmove(addr, code, len(code))
        factory = getattr(ctypes, "WINFUNCTYPE", ctypes.CFUNCTYPE)
        fn = factory(restype, *argtypes)(addr)
        _EXECUTABLE_BUFFERS.append(addr)
        return fn

    import mmap

    mm = mmap.mmap(
        -1,
        len(code),
        prot=mmap.PROT_READ | mmap.PROT_WRITE | mmap.PROT_EXEC,
    )
    mm.write(code)
    addr = ctypes.addressof(ctypes.c_char.from_buffer(mm))
    fn = ctypes.CFUNCTYPE(restype, *argtypes)(addr)
    _EXECUTABLE_BUFFERS.append(mm)
    return fn


def _cpuid(leaf: int, subleaf: int = 0) -> "tuple[int, int, int, int] | None":
    global _CPUID_FN
    if _CPUID_FN is False:
        return None
    if _CPUID_FN is None:
        try:
            if sys.platform == "win32":
                # Windows x64 calling convention: ecx=leaf, edx=subleaf, r8=out.
                code = bytes.fromhex(
                    "53"  # push rbx
                    "89c8"  # mov eax, ecx
                    "89d1"  # mov ecx, edx
                    "0fa2"  # cpuid
                    "418900"  # mov [r8], eax
                    "41895804"  # mov [r8+4], ebx
                    "41894808"  # mov [r8+8], ecx
                    "4189500c"  # mov [r8+12], edx
                    "5b"  # pop rbx
                    "c3"  # ret
                )
            else:
                # SysV x86_64 calling convention: edi=leaf, esi=subleaf,
                # rdx=out. Preserve the out pointer in r8 because CPUID
                # clobbers edx.
                code = bytes.fromhex(
                    "53"  # push rbx
                    "4989d0"  # mov r8, rdx
                    "89f8"  # mov eax, edi
                    "89f1"  # mov ecx, esi
                    "0fa2"  # cpuid
                    "418900"  # mov [r8], eax
                    "41895804"  # mov [r8+4], ebx
                    "41894808"  # mov [r8+8], ecx
                    "4189500c"  # mov [r8+12], edx
                    "5b"  # pop rbx
                    "c3"  # ret
                )
            _CPUID_FN = _make_executable_function(
                code,
                None,
                [ctypes.c_uint32, ctypes.c_uint32, ctypes.POINTER(ctypes.c_uint32)],
            )
        except Exception:
            _CPUID_FN = False
            return None
    out = (ctypes.c_uint32 * 4)()
    _CPUID_FN(ctypes.c_uint32(leaf), ctypes.c_uint32(subleaf), out)
    return int(out[0]), int(out[1]), int(out[2]), int(out[3])


def _xgetbv(index: int) -> "int | None":
    global _XGETBV_FN
    if _XGETBV_FN is False:
        return None
    if _XGETBV_FN is None:
        try:
            if sys.platform == "win32":
                # Windows x64: ecx already carries the first argument.
                code = bytes.fromhex(
                    "0f01d0"  # xgetbv
                    "48c1e220"  # shl rdx, 32
                    "4809d0"  # or rax, rdx
                    "c3"  # ret
                )
            else:
                # SysV x86_64: move first arg from edi to ecx before xgetbv.
                code = bytes.fromhex(
                    "89f9"  # mov ecx, edi
                    "0f01d0"  # xgetbv
                    "48c1e220"  # shl rdx, 32
                    "4809d0"  # or rax, rdx
                    "c3"  # ret
                )
            _XGETBV_FN = _make_executable_function(
                code,
                ctypes.c_uint64,
                [ctypes.c_uint32],
            )
        except Exception:
            _XGETBV_FN = False
            return None
    return int(_XGETBV_FN(ctypes.c_uint32(index)))


def _cpuid_cpu_flags() -> "set[str] | None":
    basic = _cpuid(0)
    if basic is None:
        return None
    max_basic = basic[0]
    if max_basic < 1:
        return None

    flags: set[str] = set()
    eax1, ebx1, ecx1, edx1 = _cpuid(1) or (0, 0, 0, 0)
    del eax1, ebx1
    if ecx1 & (1 << 0):
        flags.add("sse3")
        flags.add("pni")
    if ecx1 & (1 << 9):
        flags.add("ssse3")
    if ecx1 & (1 << 13):
        flags.add("cx16")
    if ecx1 & (1 << 19):
        flags.add("sse4_1")
    if ecx1 & (1 << 20):
        flags.add("sse4_2")
    if ecx1 & (1 << 22):
        flags.add("movbe")
    if ecx1 & (1 << 23):
        flags.add("popcnt")
    if ecx1 & (1 << 12):
        flags.add("fma")
    if ecx1 & (1 << 29):
        flags.add("f16c")

    osxsave = bool(ecx1 & (1 << 27))
    xcr0 = _xgetbv(0) if osxsave else 0
    avx_os = xcr0 is not None and (xcr0 & 0x6) == 0x6
    avx512_os = xcr0 is not None and (xcr0 & 0xE6) == 0xE6
    if (ecx1 & (1 << 28)) and avx_os:
        flags.add("avx")

    if max_basic >= 7:
        eax7, ebx7, ecx7, edx7 = _cpuid(7, 0) or (0, 0, 0, 0)
        del eax7, ecx7, edx7
        if (ebx7 & (1 << 3)) and "avx" in flags:
            flags.add("bmi1")
        if (ebx7 & (1 << 5)) and "avx" in flags:
            flags.add("avx2")
        if (ebx7 & (1 << 8)) and "avx" in flags:
            flags.add("bmi2")
        if avx512_os:
            if ebx7 & (1 << 16):
                flags.add("avx512f")
            if ebx7 & (1 << 17):
                flags.add("avx512dq")
            if ebx7 & (1 << 28):
                flags.add("avx512cd")
            if ebx7 & (1 << 30):
                flags.add("avx512bw")
            if ebx7 & (1 << 31):
                flags.add("avx512vl")

    max_ext = (_cpuid(0x80000000) or (0, 0, 0, 0))[0]
    if max_ext >= 0x80000001:
        eax8, ebx8, ecx8, edx8 = _cpuid(0x80000001) or (0, 0, 0, 0)
        del eax8, ebx8, edx8
        if ecx8 & (1 << 0):
            flags.add("lahf_lm")
        if ecx8 & (1 << 5):
            flags.add("abm")
            flags.add("lzcnt")

    return flags


def _torch_cpu_capability_level() -> "str | None":
    try:
        cap = torch.backends.cpu.get_cpu_capability().upper()
    except Exception:
        return None
    if "AVX512" in cap:
        return "x86_64_v4"
    if "AVX2" in cap:
        return "x86_64_v3"
    if "SSE4" in cap:
        return "x86_64_v2"
    return "x86_64_v1"


def _x86_64_supported_isa_levels() -> tuple[str, ...]:
    flags = _linux_cpuinfo_flags()
    if flags is None:
        flags = _cpuid_cpu_flags()
    if flags is not None:
        return tuple(
            level
            for level in _X86_64_ISA_LEVELS
            if _x86_64_flags_support_level(flags, level)
        )

    # Last-resort fallback for environments that deny executable memory for the
    # CPUID helper. PyTorch's capability string is coarser than the psABI levels
    # but is still better than speculatively loading the v4 section.
    cap_level = _torch_cpu_capability_level()
    if cap_level is None:
        return ("x86_64_v1",)
    idx = _X86_64_ISA_LEVELS.index(cap_level)
    return _X86_64_ISA_LEVELS[: idx + 1]


def _host_aot_section_keys() -> tuple[str, ...]:
    machine = platform.machine()
    if machine in ("x86_64", "AMD64"):
        levels = tuple(reversed(_x86_64_supported_isa_levels()))
        if sys.platform == "win32":
            return tuple(f"win_{level}" for level in levels)
        if sys.platform.startswith("linux"):
            return tuple(f"linux_{level}" for level in levels)
        return ()
    if sys.platform.startswith("linux") and machine in ("aarch64", "arm64"):
        return ("linux_aarch64",)
    return ()


def _getattr_symbol(dll, name: str):
    """Resolve a packed-ABI AOT symbol by its exact exported name.

    AOT sections may also expose unprefixed internal functions. Those are not
    interchangeable with the packed `_mlir_*` ABI the Python runtime calls, so
    falling back to stripped names can turn a missing packed wrapper into a
    bogus CUDA launch. Shipped sections loaded by this runtime must provide
    CuTe's exact `export_to_c` packed-wrapper symbols; if an exact symbol is
    absent, the artifact is invalid.
    """
    return getattr(dll, name)


def _resolve_ciface_name(so_bytes: bytes, ciface_prefix: str) -> str:
    """Find the exported `ciface` symbol in `so_bytes` by its stable prefix.

    The full cute-DSL ciface name is `_mlir_<variant>__mlir_ciface_<fn>`,
    where `<fn>` encodes the kernel's Python class path. The shipped manifest
    stores only `<prefix>` = `_mlir_<variant>__mlir_ciface_` (no class path),
    so the leaky tail lives only in the encrypted/in-memory `.so`. We recover
    it by scanning for the one exported packed-ABI name that starts with
    `<prefix>` — robust against arbitrary suffix content.
    """
    import struct as _struct

    needle = ciface_prefix.encode()
    if so_bytes[:4] == b"\x7fELF":
        try:
            is64 = so_bytes[4] == 2
            le = "<" if so_bytes[5] == 1 else ">"
            if is64:
                e_shoff = _struct.unpack_from(le + "Q", so_bytes, 0x28)[0]
                e_shentsize = _struct.unpack_from(le + "H", so_bytes, 0x3A)[0]
                e_shnum = _struct.unpack_from(le + "H", so_bytes, 0x3C)[0]
                for i in range(e_shnum):
                    base = e_shoff + i * e_shentsize
                    sh_type = _struct.unpack_from(le + "I", so_bytes, base + 4)[0]
                    if sh_type == 3:  # SHT_STRTAB — .dynstr or .shstrtab
                        off = _struct.unpack_from(le + "Q", so_bytes, base + 0x18)[0]
                        size = _struct.unpack_from(le + "Q", so_bytes, base + 0x20)[0]
                        blob = so_bytes[off : off + size]
                        j = blob.find(needle)
                        if j >= 0:
                            end = blob.find(b"\x00", j)
                            return blob[j:end].decode()
        except Exception:
            pass
    # Fallback: scan the whole image for the null-terminated name.
    j = so_bytes.find(needle)
    if j < 0:
        raise RuntimeError(
            f"ciface symbol with prefix {ciface_prefix!r} not found in .so"
        )
    end = so_bytes.find(b"\x00", j)
    return so_bytes[j:end].decode()


try:
    # ~0.3µs vs ~4.5µs for torch.cuda.current_stream(dev).cuda_stream —
    # the public API constructs a Stream object per call. This is the same
    # accessor torch.compile's generated wrappers use.
    _get_raw_stream = torch._C._cuda_getCurrentRawStream
except AttributeError:  # non-CUDA builds (e.g. MPS-only) lack the symbol

    def _get_raw_stream(device_index: int) -> int:
        return torch.cuda.current_stream(device_index).cuda_stream


def get_raw_stream(device_index: int) -> int:
    """Current CUDA stream handle for `device_index`, as a bare int."""
    return _get_raw_stream(device_index)


@dataclass(frozen=True, slots=True, eq=False, init=False, repr=False)
class MemrefStructSpec:
    """Layout of one `Tensor_mX_t` struct. `shape_mask`/`stride_mask` are
    per-dim 0/1 (in user layout); positions flagged 1 become slots in the
    struct's `dynamic_shapes[]` / `dynamic_strides[]` arrays."""

    shape_mask: tuple[int, ...]
    stride_mask: tuple[int, ...]
    _struct_t: type
    _shape_indices: tuple[int, ...]
    _stride_indices: tuple[int, ...]

    def __init__(self, shape_mask, stride_mask):
        shape = tuple(int(m) for m in shape_mask)
        stride = tuple(int(m) for m in stride_mask)
        shape_indices = tuple(i for i, m in enumerate(shape) if m)
        stride_indices = tuple(i for i, m in enumerate(stride) if m)
        object.__setattr__(self, "shape_mask", shape)
        object.__setattr__(self, "stride_mask", stride)
        object.__setattr__(self, "_shape_indices", shape_indices)
        object.__setattr__(self, "_stride_indices", stride_indices)
        object.__setattr__(
            self,
            "_struct_t",
            _memref_struct_type(len(shape_indices), len(stride_indices)),
        )

    def build(self, tensor: torch.Tensor):
        inst = self._struct_t()
        inst.data = tensor.data_ptr()
        if self._shape_indices:
            sh = tensor.shape
            for j, i in enumerate(self._shape_indices):
                inst.dynamic_shapes[j] = sh[i]
        if self._stride_indices:
            st = tensor.stride()
            for j, i in enumerate(self._stride_indices):
                inst.dynamic_strides[j] = st[i]
        return inst

    def to_json(self) -> dict:
        return {
            "shape_mask": list(self.shape_mask),
            "stride_mask": list(self.stride_mask),
        }

    @classmethod
    def from_json(cls, obj: dict) -> "MemrefStructSpec":
        return cls(obj["shape_mask"], obj["stride_mask"])


_MEMREF_STRUCT_CACHE: dict = {}


def _memref_struct_type(n_shapes: int, n_strides: int):
    """Cached ctypes Structure matching emitted `Tensor_mX_t`."""
    key = (n_shapes, n_strides)
    if key in _MEMREF_STRUCT_CACHE:
        return _MEMREF_STRUCT_CACHE[key]
    fields: list = [("data", ctypes.c_void_p)]
    if n_shapes > 0:
        fields.append(("dynamic_shapes", ctypes.c_int32 * n_shapes))
    if n_strides > 0:
        fields.append(("dynamic_strides", ctypes.c_int64 * n_strides))

    class _MemrefStruct(ctypes.Structure):
        _fields_ = fields

    _MEMREF_STRUCT_CACHE[key] = _MemrefStruct
    return _MemrefStruct


@dataclass(frozen=True, slots=True, eq=False, init=False, repr=False)
class CuteAotVariant:
    """One AOT-linked cute wrapper, resolved lazily on first dispatch."""

    so_path: "Path | None"
    _so_bytes: "bytes | None"
    _so_sha256: "str | None"
    _symbols: Mapping[str, str]
    _dll: "ctypes.CDLL | None"
    _ciface: "Callable | None"
    _cuda_init: "Callable | None"
    _cuda_load: "Callable | None"
    _library: ctypes.c_void_p
    _loaded_devices: set[int]
    _load_lock: object
    _ciface_name: str

    def __init__(
        self,
        symbols: dict[str, str],
        so_path: Path | None = None,
        so_bytes: bytes | None = None,
    ):
        """`symbols` maps {"cuda_init", "cuda_load_to_device", "ciface"}
        to their exported symbol names (see `cute_aot_build.aot_symbol_names`).

        Exactly one source is provided:
          * `so_bytes` — decrypted AOT `.so` from the packed `.kstlc`
            (shipped variants). Loaded via an anonymous in-memory `memfd`,
            so no plaintext `.so` is written to disk.
          * `so_path`  — a `.so` on disk (source-install JIT builds, which
            still emit a loose file under the dump dir).
        """
        if (so_path is None) == (so_bytes is None):
            raise ValueError("CuteAotVariant needs exactly one of so_path / so_bytes")
        path = Path(so_path) if so_path is not None else None
        payload = bytes(so_bytes) if so_bytes is not None else None
        symbols = MappingProxyType(dict(symbols))
        object.__setattr__(self, "so_path", path)
        object.__setattr__(self, "_so_bytes", payload)
        object.__setattr__(
            self,
            "_so_sha256",
            hashlib.sha256(payload).hexdigest() if payload is not None else None,
        )
        object.__setattr__(self, "_symbols", symbols)
        object.__setattr__(self, "_dll", None)
        object.__setattr__(self, "_ciface", None)
        object.__setattr__(self, "_cuda_init", None)
        object.__setattr__(self, "_cuda_load", None)
        object.__setattr__(self, "_library", ctypes.c_void_p(0))
        object.__setattr__(self, "_loaded_devices", set())
        # Serializes `_load` so the one-shot dlopen + function-pointer wiring
        # completes before any other thread observes `_dll` (and before the
        # only byte source, `_so_bytes`, is dropped).
        object.__setattr__(self, "_load_lock", threading.Lock())
        # Filled in `_load` once the full ciface symbol name is known; used
        # only for error messages.
        object.__setattr__(
            self,
            "_ciface_name",
            symbols.get("ciface") or symbols.get("ciface_prefix", "ciface"),
        )

    def _load(self) -> None:
        # Fast path: `_dll` is only published (last write below) after every
        # function pointer is wired, so a non-None read here means fully ready.
        if self._dll is not None:
            return
        with self._load_lock:
            # Re-check under the lock: another thread may have completed the
            # load (and cleared `_so_bytes`) while we waited.
            if self._dll is not None:
                return
            try:
                ctypes.CDLL("libcudart.so.12", mode=ctypes.RTLD_GLOBAL)
            except OSError:
                pass
            # The `ciface` export name embeds the kernel's Python class path, so
            # the shipped manifest stores only the stable `ciface_prefix`
            # (`_mlir_<variant>__mlir_ciface_`, no class path) and we recover the
            # full name from the `.so`'s dynamic string table. For packed
            # variants those bytes only ever exist in memory; JIT / loose-dir
            # variants keep the full `ciface` in their sidecar.
            ciface_name = self._symbols.get("ciface")
            cuda_init_name = self._symbols["cuda_init"]
            cuda_load_name = self._symbols["cuda_load_to_device"]
            ciface_prefix = self._symbols.get("ciface_prefix")
            if self._so_bytes is not None:
                so_bytes = self._so_bytes
                if ciface_name is None:
                    ciface_name = _resolve_ciface_name(so_bytes, ciface_prefix)
                # Decrypted-in-memory shipped variant: dlopen from an anonymous
                # fd, never materialising the plaintext `.so` on disk. Keep the
                # bytes referenced until the load fully returns.
                dll = _dlopen_from_bytes(
                    so_bytes,
                    self._symbols["cuda_init"][:24],
                    identity=self._so_sha256,
                )
            else:
                if ciface_name is None:
                    ciface_name = _resolve_ciface_name(
                        self.so_path.read_bytes(), ciface_prefix
                    )
                dll = ctypes.CDLL(str(self.so_path), mode=ctypes.RTLD_LOCAL)
            # Wire all function pointers on locals before publishing `_dll`, so
            # no other thread can see a half-initialised variant. Sections must
            # expose the exact `_mlir_*` packed ABI; PE payloads built from raw
            # LLVM IR link a C adapter that provides these exports.
            cuda_init = _getattr_symbol(dll, cuda_init_name)
            cuda_load = _getattr_symbol(dll, cuda_load_name)
            ciface = _getattr_symbol(dll, ciface_name)
            for fn in (cuda_init, cuda_load):
                fn.argtypes = [ctypes.c_void_p]
                fn.restype = None
            # `_mlir_ciface_` takes (void **args, int32_t num_args).
            ciface.argtypes = [ctypes.c_void_p, ctypes.c_int32]
            ciface.restype = None
            object.__setattr__(self, "_cuda_init", cuda_init)
            object.__setattr__(self, "_cuda_load", cuda_load)
            object.__setattr__(self, "_ciface", ciface)
            object.__setattr__(self, "_ciface_name", ciface_name)
            # Publish last: this is the gate the fast path checks.
            object.__setattr__(self, "_dll", dll)
            # Release the plaintext copy once mapped.
            object.__setattr__(self, "_so_bytes", None)

    def _ensure_device(self, device_index: int) -> None:
        if device_index in self._loaded_devices:
            return
        self._load()

        err = ctypes.c_int32(0)
        libptr = ctypes.pointer(self._library)

        dev = ctypes.c_int32(device_index)
        self._call_cuda_init_or_load(
            self._cuda_init,
            [ctypes.pointer(libptr), ctypes.pointer(err)],
            err,
            "cuda_init",
        )
        self._call_cuda_init_or_load(
            self._cuda_load,
            [ctypes.pointer(libptr), ctypes.pointer(dev), ctypes.pointer(err)],
            err,
            "cuda_load_to_device",
        )
        self._loaded_devices.add(device_index)

    @staticmethod
    def _call_cuda_init_or_load(fn, ptrs, err_slot, label):
        """Build a void*[] from `ptrs`, call `fn(packed)`, raise on
        non-zero error. Shared helper for cuda_init / cuda_load_to_device
        which differ only in how many pointer slots the cute-DSL wrapper
        reads off the packed array."""
        packed = (ctypes.c_void_p * len(ptrs))()
        for i, p in enumerate(ptrs):
            packed[i] = ctypes.cast(p, ctypes.c_void_p)
        fn(ctypes.cast(packed, ctypes.c_void_p))
        if err_slot.value:
            raise RuntimeError(f"{label} failed: rc={err_slot.value}")


class AotInvokeState:
    """Reusable per-thread invocation scratch for one AotVariantBundle.

    `invoke()` rebuilds the packed `void *[]` argument array, the memref
    structs, the stream slot, and the error slot on every call —
    ~12µs/call of ctypes allocation that dominates dispatch cost for
    kernels called hundreds of times per forward. This object allocates
    all of that once; per call it only rewrites the data pointers, the
    dynamic shape/stride values, and the stream handle in place.

    Only valid for variants with no scalar args (every cute_moe GEMM
    wrapper today — scalars stay on the classic `invoke()` path). Not
    thread-safe by construction; obtain via `bundle.invoke_state()`,
    which hands out one instance per thread.
    """

    __slots__ = (
        "_bundle",
        "_specs",
        "_structs",
        "_packed",
        "_packed_addr",
        "_err",
        "_stream",
        "_n_memrefs",
    )

    def __init__(self, bundle: "AotVariantBundle") -> None:
        if bundle._scalar_arg_indices:
            raise RuntimeError(
                "AotInvokeState does not support scalar args; use invoke()"
            )
        self._bundle = bundle
        self._specs = bundle.memref_specs
        self._n_memrefs = len(bundle.memref_specs)
        self._structs = [spec._struct_t() for spec in bundle.memref_specs]
        self._packed = bundle._packed_type()
        for slot, inst in zip(bundle._memref_arg_indices, self._structs):
            self._packed[slot] = ctypes.addressof(inst)
        self._err = ctypes.c_int32(0)
        self._packed[bundle._err_slot] = ctypes.addressof(self._err)
        self._stream = ctypes.c_void_p(0)
        stream_addr = ctypes.addressof(self._stream)
        for slot in bundle._stream_arg_indices:
            self._packed[slot] = stream_addr
        self._packed_addr = ctypes.cast(self._packed, ctypes.c_void_p)

    def invoke(self, tensors: list, raw_stream: int) -> None:
        if len(tensors) != self._n_memrefs:
            raise RuntimeError(
                f"memref count mismatch: expected {self._n_memrefs}, got {len(tensors)}"
            )
        for spec, inst, t in zip(self._specs, self._structs, tensors):
            inst.data = t.data_ptr()
            idxs = spec._shape_indices
            if idxs:
                sh = t.shape
                arr = inst.dynamic_shapes
                for j, i in enumerate(idxs):
                    arr[j] = sh[i]
            idxs = spec._stride_indices
            if idxs:
                st = t.stride()
                arr = inst.dynamic_strides
                for j, i in enumerate(idxs):
                    arr[j] = st[i]
        self._stream.value = raw_stream
        self._err.value = 0
        self._bundle._invoke_packed(self._packed_addr, self._err)


class AotPreparedInvoke:
    """One fixed AOT argument pack reusable by a stable serving slot."""

    __slots__ = ("_bundle", "_packed", "_packed_addr", "_err", "_keepalive")

    def __init__(self, bundle, memrefs, scalars, stream) -> None:
        if len(memrefs) != len(bundle._memref_arg_indices):
            raise RuntimeError(
                f"memref count mismatch: expected {len(bundle._memref_arg_indices)}, "
                f"got {len(memrefs)}"
            )
        if len(scalars) != len(bundle._scalar_arg_indices):
            raise RuntimeError(
                f"scalar count mismatch: expected {len(bundle._scalar_arg_indices)}, "
                f"got {len(scalars)}"
            )
        packed = bundle._packed_type()
        for slot, memref in zip(bundle._memref_arg_indices, memrefs):
            packed[slot] = ctypes.addressof(memref)
        for slot, scalar in zip(bundle._scalar_arg_indices, scalars):
            packed[slot] = ctypes.addressof(scalar)
        stream_addr = ctypes.addressof(stream)
        for slot in bundle._stream_arg_indices:
            packed[slot] = stream_addr
        err = ctypes.c_int32(0)
        packed[bundle._err_slot] = ctypes.addressof(err)
        self._bundle = bundle
        self._packed = packed
        self._packed_addr = ctypes.cast(packed, ctypes.c_void_p)
        self._err = err
        self._keepalive = (tuple(memrefs), tuple(scalars), stream)

    def invoke(self) -> None:
        self._err.value = 0
        self._bundle._invoke_packed(self._packed_addr, self._err)


@dataclass(frozen=True, slots=True, eq=False, init=False, repr=False)
class AotVariantBundle:
    """One immutable `.so`, receipt, and argument-ABI binding, ready to invoke."""

    aot: CuteAotVariant
    memref_specs: tuple
    arg_kinds: tuple[str, ...]
    _packed_type: type
    _num_args: int
    _err_slot: int
    _memref_arg_indices: tuple[int, ...]
    _scalar_arg_indices: tuple[int, ...]
    _stream_arg_indices: tuple[int, ...]
    _tls: threading.local
    _packed_artifact_receipt_json: "str | None"

    def __init__(
        self,
        aot: CuteAotVariant,
        memref_specs: tuple,
        arg_kinds: list,
        *,
        _packed_artifact_receipt_json: "str | None" = None,
    ) -> None:
        specs = tuple(memref_specs)
        kinds = tuple(arg_kinds)
        memref_arg_indices = tuple(
            i for i, kind in enumerate(kinds) if kind == "memref"
        )
        scalar_arg_indices = tuple(
            i for i, kind in enumerate(kinds) if kind == "scalar"
        )
        stream_arg_indices = tuple(
            i for i, kind in enumerate(kinds) if kind == "stream"
        )
        known = (
            len(memref_arg_indices) + len(scalar_arg_indices) + len(stream_arg_indices)
        )
        if known != len(kinds):
            unknown = sorted(set(kinds) - {"memref", "scalar", "stream"})
            raise RuntimeError(f"unknown AOT arg kinds: {unknown}")
        num_args = len(kinds) + 1  # +1 for trailing error slot
        object.__setattr__(self, "aot", aot)
        object.__setattr__(self, "memref_specs", specs)
        object.__setattr__(self, "arg_kinds", kinds)
        object.__setattr__(
            self,
            "_packed_artifact_receipt_json",
            _packed_artifact_receipt_json,
        )
        object.__setattr__(self, "_tls", threading.local())
        object.__setattr__(self, "_packed_type", ctypes.c_void_p * num_args)
        object.__setattr__(self, "_num_args", num_args)
        object.__setattr__(self, "_err_slot", len(kinds))
        object.__setattr__(self, "_memref_arg_indices", memref_arg_indices)
        object.__setattr__(self, "_scalar_arg_indices", scalar_arg_indices)
        object.__setattr__(self, "_stream_arg_indices", stream_arg_indices)

    def invoke_state(self) -> AotInvokeState:
        """Per-thread reusable invocation state (no-scalar variants only)."""
        state = getattr(self._tls, "state", None)
        if state is None:
            state = AotInvokeState(self)
            self._tls.state = state
        return state

    def prepare_invoke(self, memrefs, scalars, stream) -> AotPreparedInvoke:
        """Pack fixed wrapper arguments once for repeated serving launches."""

        return AotPreparedInvoke(self, memrefs, scalars, stream)

    def _invoke_packed(self, packed: "ctypes.c_void_p", err: ctypes.c_int32) -> None:
        """Invoke one prepared packed call and record its shipped identity on success."""

        receipt_json = self._packed_artifact_receipt_json
        if receipt_json is not None:
            from kestrel_kernels.cubin_runtime import (
                _discard_packed_artifact_receipt_capture,
                _record_packed_artifact_receipt_json_from_capture,
                _snapshot_packed_artifact_receipt_capture,
            )

            capture = _snapshot_packed_artifact_receipt_capture()
        try:
            self.aot._ciface(packed, self._num_args)
        except BaseException:
            if receipt_json is not None:
                _discard_packed_artifact_receipt_capture(capture)
            raise
        if err.value:
            if receipt_json is not None:
                _discard_packed_artifact_receipt_capture(capture)
            raise RuntimeError(f"{self.aot._ciface_name}: rc={err.value}")
        if receipt_json is not None:
            _record_packed_artifact_receipt_json_from_capture(receipt_json, capture)

    def invoke(self, memrefs: list, scalars: list, stream: "ctypes.c_void_p") -> None:
        if len(memrefs) != len(self._memref_arg_indices):
            raise RuntimeError(
                f"memref count mismatch: expected {len(self._memref_arg_indices)}, "
                f"got {len(memrefs)}"
            )
        if len(scalars) != len(self._scalar_arg_indices):
            raise RuntimeError(
                f"scalar count mismatch: expected {len(self._scalar_arg_indices)}, "
                f"got {len(scalars)}"
            )

        packed = self._packed_type()
        for slot, memref in zip(self._memref_arg_indices, memrefs):
            packed[slot] = ctypes.addressof(memref)
        for slot, scalar in zip(self._scalar_arg_indices, scalars):
            packed[slot] = ctypes.addressof(scalar)
        stream_addr = ctypes.addressof(stream)
        for slot in self._stream_arg_indices:
            packed[slot] = stream_addr
        err = ctypes.c_int32(0)
        packed[self._err_slot] = ctypes.addressof(err)
        self._invoke_packed(ctypes.cast(packed, ctypes.c_void_p), err)


@dataclass(frozen=True, init=False)
class _AotShippedResolution:
    """The exact packed entry and wrapper selected by archive priority."""

    bundle: AotVariantBundle
    inventory_variant_key: str
    _variant_metadata_snapshot: dict

    def __init__(
        self,
        bundle: AotVariantBundle,
        variant_metadata: Mapping,
        *,
        inventory_variant_key: str,
    ) -> None:
        object.__setattr__(self, "bundle", bundle)
        object.__setattr__(
            self,
            "inventory_variant_key",
            inventory_variant_key,
        )
        object.__setattr__(
            self,
            "_variant_metadata_snapshot",
            deepcopy(dict(variant_metadata)),
        )

    @property
    def variant_metadata(self) -> dict:
        """Return detached build metadata for the exact selected wrapper."""

        return deepcopy(self._variant_metadata_snapshot)

    @property
    def receipt(self) -> dict:
        """Return a detached copy of the compact packed-entry identity."""

        receipt_json = self.bundle._packed_artifact_receipt_json
        if receipt_json is None:
            raise RuntimeError("shipped AOT bundle has no packed artifact receipt")
        return json.loads(receipt_json)


class AotFamily:
    """Resolves AOT-emitted cute wrappers for one kernel family.

    Metadata source priority:
      1. Shipped family manifest inside `bundles.kstlc`
         (`variants[variant_key].aot`).
      2. Sidecar JSON (`<so_path>.aot.json`) for JIT-built variants.

    When `jit_compile_fn` is provided, cache misses compile on demand
    via `build_aot_variant` (source install only). The factory takes
    the `variant` object passed to `resolve()` and returns a
    `compile_fn(arch) -> (kernel_target, *fake_args)` suitable for
    `cute.compile()`.
    """

    def __init__(
        self,
        family_name: str,
        jit_compile_fn: Callable[[object], Callable[[str], tuple]] | None = None,
    ):
        self.family_name = family_name
        self.jit_compile_fn = jit_compile_fn
        self._cache: dict[tuple[str, str], AotVariantBundle] = {}
        self._shipped_cache: dict[tuple[str, str], _AotShippedResolution] = {}
        self._manifests: "tuple[dict, ...] | None" = None

    @property
    def bundle_dir(self) -> Path:
        # Multi-process tuners compile independent candidate sets. Keep their
        # loose JIT wrappers out of the installed package and out of each
        # other's build target; packed production manifests are still read
        # from KERNEL_DIR by `_load_manifests`.
        jit_root = os.environ.get("KESTREL_CUTE_AOT_JIT_DIR")
        if jit_root:
            return Path(jit_root) / self.family_name
        # On multi-CUDA aarch64 wheels, ``kestrel_kernels.KERNEL_DIR`` points
        # at the cu<major>/ subdir matching torch's CUDA major; the
        # cute-dsl AOT shared libs in ``bundles/<family>/`` link against
        # cuBLAS/cuBLASLt/cudart for that major.
        from kestrel_kernels import KERNEL_DIR

        return KERNEL_DIR / "bundles" / self.family_name

    def _load_manifests(self) -> "tuple[dict, ...]":
        if self._manifests is None:
            from kestrel_kernels.cubin_runtime import load_packed_family_manifests

            self._manifests = load_packed_family_manifests(self.family_name)
        return self._manifests

    @staticmethod
    def _meta_from_aot(aot_meta: dict):
        symbols = aot_meta.get("symbols")
        arg_kinds = aot_meta.get("arg_kinds")
        specs_list = aot_meta.get("memref_specs")
        if symbols and arg_kinds and specs_list:
            return (
                symbols,
                list(arg_kinds),
                tuple(MemrefStructSpec.from_json(s) for s in specs_list),
            )
        return None

    def _iter_shipped_records(self, variant_key: str, arch: str):
        """Yield viable packaged records in the exact runtime resolution order."""
        from kestrel_kernels.cubin_runtime import (
            _candidate_arch_keys,
            decode_protected_section_do_not_extract_or_redistribute,
        )

        for mf in self._load_manifests():
            variant = mf.get("variants", {}).get(variant_key)
            if variant is None:
                continue
            meta = self._meta_from_aot(variant.get("aot") or {})
            if meta is None:
                continue
            archs = variant.get("architectures", {})
            entry = None
            for candidate in _candidate_arch_keys(arch):
                if candidate in archs:
                    entry = archs[candidate]
                    break
            if entry is None:
                continue

            aot_sections = entry.get("aot_sections")
            if aot_sections:
                host_keys = _host_aot_section_keys()
                for key in host_keys:
                    section = aot_sections.get(key)
                    if section is None:
                        continue
                    so_bytes = decode_protected_section_do_not_extract_or_redistribute(mf, section)
                    if _so_bytes_match_host(so_bytes):
                        yield mf, str(candidate), variant, meta, so_bytes

    def _iter_shipped_entries(self, variant_key: str, arch: str):
        """Yield viable packaged entries in archive-priority order."""
        for (
            _manifest,
            _selected_arch,
            variant,
            meta,
            so_bytes,
        ) in self._iter_shipped_records(variant_key, arch):
            yield variant, meta, so_bytes

    def _reuse_jit_build(self, variant_key: str, arch: str):
        """Reuse a `.so` a previous in-process JIT build left on disk.

        Source-install JIT builds write a loose `<variant>_<arch>.so` plus an
        `.aot.json` sidecar under the dump dir; a later run with the same
        variant reloads it instead of recompiling. Shipped wheels never hit
        this path (they resolve from the packed `.kstlc`).
        """
        so_path = self.bundle_dir / f"{variant_key}_{arch}{_SHARED_LIB_EXT}"
        sidecar = so_path.with_suffix(".aot.json")
        if not (so_path.exists() and sidecar.exists()):
            return None
        try:
            meta = self._meta_from_aot(json.loads(sidecar.read_text()))
        except Exception:
            return None
        if meta is None:
            return None
        return so_path, meta

    def shipped_variant_metadata(
        self,
        variant_key: str,
        arch: "str | None" = None,
    ) -> "dict | None":
        """Return immutable build metadata for one packaged variant, if present."""

        from kestrel_kernels.arch import get_cuda_arch

        resolved_arch = get_cuda_arch() if arch is None else str(arch)
        resolved = self._resolve_shipped_with_receipt(
            str(variant_key),
            resolved_arch,
        )
        if resolved is None:
            return None
        return resolved.variant_metadata

    def shipped_artifact_receipt(
        self,
        variant_key: str,
        arch: "str | None" = None,
    ) -> "dict | None":
        """Return the detached identity of the selected packed wrapper only."""

        from kestrel_kernels.arch import get_cuda_arch

        resolved_arch = get_cuda_arch() if arch is None else str(arch)
        resolved = self._resolve_shipped_with_receipt(
            str(variant_key),
            resolved_arch,
        )
        if resolved is None:
            return None
        return resolved.receipt

    def _packed_receipt_json(
        self,
        variant_key: str,
        manifest: dict,
        selected_arch: str,
        wrapper_sha256: str,
    ) -> str:
        archive_path = manifest.get("_kstlc_path")
        archive_data = manifest.get("_kstlc_data")
        archive_root = manifest.get("_kstlc_root")
        if (
            not isinstance(archive_path, str)
            or not archive_path
            or not isinstance(archive_data, bytes)
            or not isinstance(archive_root, str)
            or not archive_root
        ):
            raise RuntimeError(
                f"packed {self.family_name!r} manifest lacks archive identity"
            )
        resolved_archive_path = str(Path(archive_path).resolve())
        archive_size_bytes = len(archive_data)
        from kestrel_kernels.cubin_runtime import _kstlc_archive_sha256

        archive_sha256 = _kstlc_archive_sha256(manifest)
        from kestrel_kernels.cubin_runtime import (
            _legacy_build_toolchain_sha256,
            _require_canonical_sha256,
        )
        manifest_content_fingerprint = _require_canonical_sha256(
            manifest.get("manifest_content_fingerprint"),
            field="manifest_content_fingerprint",
        )
        inventory_fingerprint = _require_canonical_sha256(
            manifest.get("inventory_fingerprint"), field="inventory_fingerprint"
        )
        toolchain_sha256 = _legacy_build_toolchain_sha256(manifest)
        receipt = {
                "schema_version": 1,
                "family": self.family_name,
                "variant_key": str(variant_key),
                "architecture": selected_arch,
                "manifest_content_fingerprint": manifest_content_fingerprint,
                "inventory_fingerprint": inventory_fingerprint,
                "wrapper_sha256": wrapper_sha256,
                "payload_kind": "aot_wrapper",
                "payload_sha256": wrapper_sha256,
                "archive_path": resolved_archive_path,
                "archive_size_bytes": archive_size_bytes,
                "archive_sha256": archive_sha256,
                "archive_root": archive_root,
            }
        if toolchain_sha256 is not None:
            receipt["build_toolchain_sha256"] = toolchain_sha256
        return json.dumps(
            receipt,
            sort_keys=True,
            separators=(",", ":"),
        )

    def _resolve_shipped_with_receipt(
        self,
        variant,
        arch: str,
    ) -> "_AotShippedResolution | None":
        """Resolve one packed wrapper, metadata, and identity in one scan."""

        variant_key = getattr(variant, "variant_key", variant)
        cache_key = (variant_key, arch)
        cached = self._shipped_cache.get(cache_key)
        if cached is not None:
            return cached
        resolved = next(self._iter_shipped_records(variant_key, arch), None)
        if resolved is None:
            return None
        manifest, selected_arch, entry, meta, so_bytes = resolved
        symbols, arg_kinds, memref_specs = meta
        metadata = entry.get("variant")
        if metadata is None:
            metadata = {}
        elif not isinstance(metadata, Mapping):
            return None
        aot = CuteAotVariant(symbols, so_bytes=so_bytes)
        receipt_json = self._packed_receipt_json(
            str(variant_key),
            manifest,
            selected_arch,
            aot._so_sha256,
        )
        bundle = AotVariantBundle(
            aot=aot,
            memref_specs=memref_specs,
            arg_kinds=arg_kinds,
            _packed_artifact_receipt_json=receipt_json,
        )
        result = _AotShippedResolution(
            bundle=bundle,
            variant_metadata=metadata,
            inventory_variant_key=entry.get(
                "inventory_variant_key", variant_key
            ),
        )
        self._shipped_cache[cache_key] = result
        return result

    def resolve_shipped(self, variant, arch: str) -> "AotVariantBundle | None":
        """Resolve only a packed artifact; never reuse or build a loose JIT wrapper."""

        resolved = self._resolve_shipped_with_receipt(variant, arch)
        if resolved is None:
            return None
        return resolved.bundle

    def resolve(self, variant, arch: str) -> "AotVariantBundle | None":
        """Look up or build the AOT wrapper for `(variant, arch)`.

        `variant` may be any object with a `.variant_key` attribute, or
        a bare string. Returns None if no shipped variant exists and
        JIT is disabled / fails.
        """
        variant_key = getattr(variant, "variant_key", variant)
        cache_key = (variant_key, arch)
        cached = self._cache.get(cache_key)
        if cached is not None:
            return cached

        shipped = self._resolve_shipped_with_receipt(variant, arch)
        if shipped is not None:
            bundle = shipped.bundle
            self._cache[cache_key] = bundle
            return bundle

        so_path = None
        so_bytes = None
        if (
            self.jit_compile_fn is not None
            and (reused := self._reuse_jit_build(variant_key, arch)) is not None
        ):
            so_path, (symbols, arg_kinds, memref_specs) = reused
        else:
            if self.jit_compile_fn is None:
                return None
            try:
                jit_so_path = self.bundle_dir / f"{variant_key}_{arch}{_SHARED_LIB_EXT}"
                so_path, symbols, arg_kinds, memref_specs = self._jit_build(
                    variant,
                    arch,
                    jit_so_path,
                )
            except Exception as exc:
                # Surface the underlying compile failure when KESTREL_CUTE_JIT_DEBUG=1.
                # Otherwise silently fall back so the caller's "set
                # KESTREL_CUTE_JIT=1" hint stays accurate when JIT is off.
                import os
                import traceback

                if os.environ.get("KESTREL_CUTE_JIT_DEBUG") == "1":
                    print(
                        f"[AotFamily] JIT build failed for {variant_key} on {arch}: "
                        f"{type(exc).__name__}: {exc}",
                        flush=True,
                    )
                    traceback.print_exc()
                return None

        bundle = AotVariantBundle(
            aot=CuteAotVariant(
                symbols,
                so_path=so_path,
                so_bytes=so_bytes,
            ),
            memref_specs=memref_specs,
            arg_kinds=arg_kinds,
        )
        self._cache[cache_key] = bundle
        return bundle

    def _jit_build(self, variant, arch: str, so_path: Path):
        import cutlass.cute as cute
        from scripts.precompile import cubin_bundles as _cubin_bundles
        from scripts.precompile.cute_aot_build import (
            build_aot_variant,
            aot_symbol_names,
            aot_arg_abi,
            aot_arg_kinds,
        )

        compile_fn = self.jit_compile_fn(variant)
        fn_args = compile_fn(arch)
        kernel_target, *args = fn_args
        options = _cubin_bundles.cute_compile_options_for_target_arch(arch)
        extra_options = getattr(compile_fn, "extra_compile_options", "")
        if extra_options:
            options = f"{options} {extra_options}"
        with _cubin_bundles.target_arch_env(arch):
            compiled = cute.compile(
                kernel_target,
                *args,
                options=options,
            )

        variant_key = getattr(variant, "variant_key", variant)
        so_path.parent.mkdir(parents=True, exist_ok=True)
        build_aot_variant(compiled, variant_key, so_path)
        symbols = aot_symbol_names(variant_key, compiled.function_name)
        arg_abi = aot_arg_abi(compiled)
        arg_kinds = aot_arg_kinds(compiled)
        memref_specs = tuple(
            MemrefStructSpec(
                shape_mask=list(a.dynamic_shapes_mask),
                stride_mask=list(a.dynamic_strides_mask),
            )
            for a in args
            if hasattr(a, "dynamic_shapes_mask")
        )

        so_path.with_suffix(".aot.json").write_text(
            json.dumps(
                {
                    "symbols": symbols,
                    "arg_kinds": arg_kinds,
                    "arg_abi": arg_abi,
                    "memref_abi": [
                        entry["name"] for entry in arg_abi if entry["kind"] == "memref"
                    ],
                    "memref_specs": [s.to_json() for s in memref_specs],
                }
            )
        )

        return so_path, symbols, arg_kinds, memref_specs


__all__ = [
    "AotFamily",
    "AotInvokeState",
    "AotVariantBundle",
    "CuteAotVariant",
    "MemrefStructSpec",
    "get_raw_stream",
]
